import React, { useState, useEffect } from 'react';
import { getGraphSummary, getGraphConfidence, getGraphTimeline } from '../services/api';
import { Line, Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  LineElement, BarElement, PointElement,
  LinearScale, CategoryScale,
  Filler, Tooltip, Legend
} from 'chart.js';

ChartJS.register(
  LineElement, BarElement, PointElement,
  LinearScale, CategoryScale,
  Filler, Tooltip, Legend
);

const gridColor  = '#1e2d47';
const tickStyle  = { color: '#64748b', font: { size: 9 } };

export default function GraphsPage() {
  const [summary,    setSummary]    = useState([]);
  const [confidence, setConfidence] = useState({});
  const [timeline,   setTimeline]   = useState({ labels: [], counts: [] });
  const [loading,    setLoading]    = useState(true);
  const [lastUpdate, setLastUpdate] = useState('');

  const loadData = async () => {
    try {
      const [sumRes, confRes, timeRes] = await Promise.all([
        getGraphSummary(),
        getGraphConfidence(),
        getGraphTimeline()
      ]);
      setSummary(sumRes.data.data          || []);
      setConfidence(confRes.data.classes   || {});
      setTimeline({
        labels: timeRes.data.labels || [],
        counts: timeRes.data.counts || []
      });
      setLastUpdate(new Date().toLocaleTimeString());
    } catch (err) {
      console.warn('[Graphs] Failed to load:', err);
    } finally {
      setLoading(false);
    }
  };

  // Load on mount + refresh every 10 seconds
  useEffect(() => {
    loadData();
    // Refresh every 5 seconds — live data
    const id = setInterval(loadData, 5000);
    return () => clearInterval(id);
}, []);

  // ── Chart data ───────────────────────────────────────────────
  const confChartData = {
    labels: Array.from(
      { length: Math.max(...Object.values(confidence).map(v => v.length), 1) },
      (_, i) => i + 1
    ),
    datasets: Object.entries(confidence).map(([cls, points]) => ({
      label:       cls,
      data:        points.map(p => p.confidence),
      borderColor: {
        Fire:       '#fb923c',
        Smoke:      '#94a3b8',
        Gun:        '#f87171',
        Knife:      '#facc15',
        Falling:    '#a78bfa',
        Violence:   '#f43f5e',
        Theft_Mask: '#fbbf24'
      }[cls] || '#ffffff',
      borderWidth:  1.5,
      pointRadius:  3,
      fill:         false,
      tension:      0.4
    }))
  };

  const timelineChartData = {
    labels:   timeline.labels,
    datasets: [{
      label:           'Detections',
      data:            timeline.counts,
      borderColor:     '#3b82f6',
      borderWidth:     2,
      fill:            true,
      backgroundColor: 'rgba(59,130,246,.08)',
      pointRadius:     0,
      tension:         0.4
    }]
  };

  const summaryChartData = {
    labels:   summary.map(s => s.class_name),
    datasets: [{
      label:           'Count',
      data:            summary.map(s => s.count),
      backgroundColor: summary.map(s => `${s.color}cc`),
      borderColor:     summary.map(s => s.color),
      borderWidth:     1,
      borderRadius:    4
    }]
  };

  const baseOpts = {
    animation:   false,
    responsive:  true,
    plugins: { legend: { display: false } },
    scales: {
      x: { ticks: { ...tickStyle, maxTicksLimit: 8 }, grid: { color: gridColor } },
      y: { ticks: tickStyle,                          grid: { color: gridColor } }
    }
  };

  const confOpts = {
    ...baseOpts,
    plugins: {
      legend: {
        display:  true,
        position: 'bottom',
        labels:   { color: '#64748b', font: { size: 9 }, boxWidth: 10, padding: 8 }
      }
    },
    scales: {
      x: { ticks: tickStyle,                                    grid: { color: gridColor } },
      y: { min: 0, max: 1, ticks: { ...tickStyle, stepSize: .25 }, grid: { color: gridColor } }
    }
  };

  if (loading) {
    return (
      <div style={{
        flex: 1, display: 'flex',
        alignItems: 'center', justifyContent: 'center',
        color: '#64748b', fontSize: 13
      }}>
        Loading graphs...
      </div>
    );
  }

  return (
    <div style={{ padding: '14px 16px', height: '100%', overflowY: 'auto' }}>

      {/* Header */}
      <div style={{
        display:        'flex',
        justifyContent: 'space-between',
        alignItems:     'center',
        marginBottom:   16
      }}>
        <div>
          <h2 style={{ fontSize: 16, fontWeight: 700, color: '#fff', margin: 0 }}>
            Analytics & Graphs
          </h2>
          <p style={{ fontSize: 11, color: '#64748b', margin: '3px 0 0' }}>
            Real-time detection analytics
          </p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          {lastUpdate && (
            <span style={{ fontSize: 10, color: '#64748b' }}>
              Updated: {lastUpdate}
            </span>
          )}
          <button
            onClick={loadData}
            style={{
              background:   '#151d2e',
              border:       '1px solid #1e2d47',
              color:        '#94a3b8',
              padding:      '5px 12px',
              borderRadius: 6,
              fontSize:     11,
              cursor:       'pointer'
            }}
          >
            ↺ Refresh
          </button>
        </div>
      </div>

      {/* Stats row */}
      <div style={{
        display:             'grid',
        gridTemplateColumns: 'repeat(4,1fr)',
        gap:                 8,
        marginBottom:        16
      }}>
        {[
          {
            label: 'Total Detections',
            value: summary.reduce((a, b) => a + b.count, 0),
            color: '#60a5fa'
          },
          {
            label: 'Threat Events',
            value: summary
              .filter(s => ['Fire','Gun','Knife','Violence','Smoke','Falling','Theft_Mask']
              .includes(s.class_name))
              .reduce((a, b) => a + b.count, 0),
            color: '#f87171'
          },
          {
            label: 'Normal Events',
            value: summary.find(s => s.class_name === 'Normal')?.count || 0,
            color: '#22c55e'
          },
          {
            label: 'Classes Active',
            value: summary.filter(s => s.count > 0).length,
            color: '#a78bfa'
          }
        ].map((stat, i) => (
          <div key={i} style={{
            background:   '#151d2e',
            border:       '1px solid #1e2d47',
            borderRadius: 8,
            padding:      '10px 14px'
          }}>
            <div style={{ fontSize: 10, color: '#64748b', marginBottom: 4 }}>
              {stat.label}
            </div>
            <div style={{ fontSize: 22, fontWeight: 700, color: stat.color }}>
              {stat.value}
            </div>
          </div>
        ))}
      </div>

      {/* Charts grid */}
      <div style={{
        display:             'grid',
        gridTemplateColumns: '1fr 1fr',
        gap:                 12,
        marginBottom:        12
      }}>

        {/* Confidence Score Graph */}
        <div style={{
          background:   '#151d2e',
          border:       '1px solid #1e2d47',
          borderRadius: 8,
          padding:      12
        }}>
          <div style={{
            display:        'flex',
            justifyContent: 'space-between',
            alignItems:     'center',
            marginBottom:   10
          }}>
            <span style={{
              fontSize:      11,
              fontWeight:    700,
              color:         '#94a3b8',
              textTransform: 'uppercase',
              letterSpacing: '.5px'
            }}>
              Confidence Score Graph
            </span>
            <span style={{
              fontSize:     9,
              color:        '#64748b',
              background:   '#0a0e1a',
              padding:      '2px 6px',
              borderRadius: 4
            }}>
              Threat Classes
            </span>
          </div>

          {Object.keys(confidence).length === 0 ? (
            <div style={{
              height:         160,
              display:        'flex',
              alignItems:     'center',
              justifyContent: 'center',
              color:          '#64748b',
              fontSize:       11
            }}>
              No threat detections yet
            </div>
          ) : (
            <Line data={confChartData} options={confOpts} height={160} />
          )}
        </div>

        {/* Detections Over Time */}
        <div style={{
          background:   '#151d2e',
          border:       '1px solid #1e2d47',
          borderRadius: 8,
          padding:      12
        }}>
          <div style={{
            display:        'flex',
            justifyContent: 'space-between',
            alignItems:     'center',
            marginBottom:   10
          }}>
            <span style={{
              fontSize:      11,
              fontWeight:    700,
              color:         '#94a3b8',
              textTransform: 'uppercase',
              letterSpacing: '.5px'
            }}>
              Detections Over Time
            </span>
            <span style={{
              fontSize:     9,
              color:        '#64748b',
              background:   '#0a0e1a',
              padding:      '2px 6px',
              borderRadius: 4
            }}>
              Today (24h)
            </span>
          </div>
          <Line data={timelineChartData} options={baseOpts} height={160} />
        </div>

      </div>

      {/* Detection Summary Bar Chart */}
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      12
      }}>
        <div style={{
          display:        'flex',
          justifyContent: 'space-between',
          alignItems:     'center',
          marginBottom:   10
        }}>
          <span style={{
            fontSize:      11,
            fontWeight:    700,
            color:         '#94a3b8',
            textTransform: 'uppercase',
            letterSpacing: '.5px'
          }}>
            Detection Summary — All Classes
          </span>
          <span style={{
            fontSize:     9,
            color:        '#64748b',
            background:   '#0a0e1a',
            padding:      '2px 6px',
            borderRadius: 4
          }}>
            Today
          </span>
        </div>

        {summary.every(s => s.count === 0) ? (
          <div style={{
            height:         100,
            display:        'flex',
            alignItems:     'center',
            justifyContent: 'center',
            color:          '#64748b',
            fontSize:       11
          }}>
            No detections yet today
          </div>
        ) : (
          <Bar data={summaryChartData} options={baseOpts} height={80} />
        )}
      </div>

    </div>
  );
}
